@Service
public class BankTransferService {
    @Autowired
    private AccountRepository accountRepo;

    @Transactional  // Spring enforces ACID properties
    public void transferMoney(Long fromId, Long toId, BigDecimal amount) {
        var fromAccount = accountRepo.findById(fromId)
            .orElseThrow(() -> new AccountNotFoundException(fromId));
        var toAccount = accountRepo.findById(toId)
            .orElseThrow(() -> new AccountNotFoundException(toId));

        // Atomicity: both operations succeed or both fail
        fromAccount.debit(amount);  // throws if insufficient funds
        toAccount.credit(amount);

        accountRepo.save(fromAccount);  // Consistency: balance constraints checked
        accountRepo.save(toAccount);    // Isolation: other transactions see old or new state, not in-between
        // Durability: after commit, changes survive crashes
    }
}

@Service
public class OrderService {
    @Autowired
    private OrderRepository orderRepo;
    @Autowired
    private InventoryService inventoryService;

    @Transactional  // Spring starts transaction here
    public Order createOrder(OrderRequest request) {
        var order = new Order(request.customerId(), request.items());
        orderRepo.save(order);  // persisted in transaction

        inventoryService.reserveStock(request.items());  // also in same transaction

        return order;  // Spring commits transaction on successful return
    }

    @Transactional(readOnly = true)  // optimization for read-only operations
    public Optional<Order> findOrder(Long orderId) {
        return orderRepo.findById(orderId);  // read-only transaction
    }
    // If createOrder throws RuntimeException, Spring rolls back automatically
}

